import{b as o,O as a,g as e,j as l}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"Google 测试体系","description":"","frontmatter":{},"headers":[],"relativePath":"testing/engineering/google-testing/index.md","filePath":"测试理论与实践/4.现代测试工程/13.Google测试体系.md","lastUpdated":1781688244000}'),n={name:"testing/engineering/google-testing/index.md"};function r(i,t,s,d,u,h){return a(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="google-测试体系" tabindex="-1">Google 测试体系 <a class="header-anchor" href="#google-测试体系" aria-label="Permalink to &quot;Google 测试体系&quot;">​</a></h1><blockquote><p>Google 的测试体系不是&quot;大厂用了什么工具&quot;的清单，而是一套完整的组织设计——从角色分工到测试分层，从质量门禁到生产力工程，把质量内建到开发流程的每一个环节。</p></blockquote><h2 id="质量内建的三个角色" tabindex="-1">质量内建的三个角色 <a class="header-anchor" href="#质量内建的三个角色" aria-label="Permalink to &quot;质量内建的三个角色&quot;">​</a></h2><p>Google 测试体系最独特的设计，是把测试相关的工作拆成了三个角色。这不是&quot;测试部的三种岗位&quot;，而是<strong>三种质量视角嵌入到整个开发生命周期</strong>。</p><table tabindex="0"><thead><tr><th>角色</th><th>缩写</th><th>定位</th><th>日常做什么</th></tr></thead><tbody><tr><td><strong>软件开发工程师</strong></td><td>SWE</td><td>功能开发 + 质量第一责任人</td><td>写代码、写单元测试、对代码质量直接负责</td></tr><tr><td><strong>测试开发工程师</strong></td><td>SET</td><td>偏开发侧的测试角色</td><td>写测试框架、测试工具、自动化基础设施，关注可测试性</td></tr><tr><td><strong>测试工程师</strong></td><td>TE</td><td>偏用户侧的测试角色</td><td>探索式测试、场景测试、用户行为验证，关注端到端体验</td></tr></tbody></table><h3 id="swe-质量从代码开始" tabindex="-1">SWE：质量从代码开始 <a class="header-anchor" href="#swe-质量从代码开始" aria-label="Permalink to &quot;SWE：质量从代码开始&quot;">​</a></h3><p>Google 的基本理念是开发者对质量负首要责任。SWE 不只是&quot;写完功能就扔给测试&quot;——他们需要为自己的代码写单元测试（小型测试），参与代码审查，在提交前确保测试通过。</p><blockquote><p>如果你写了一段代码但没有测试，在 Google 这不是&quot;还没测&quot;的状态，而是&quot;没完成&quot;的状态。</p></blockquote><h3 id="set-让测试可行、可规模化" tabindex="-1">SET：让测试可行、可规模化 <a class="header-anchor" href="#set-让测试可行、可规模化" aria-label="Permalink to &quot;SET：让测试可行、可规模化&quot;">​</a></h3><p>SET 的本质是&quot;以测试为方向的开发者&quot;。他们不测具体功能，而是<strong>建造测试的基础设施</strong>——测试框架、CI 集成、Mock 工具、测试数据工厂。SET 的关注点是：</p><ul><li><strong>可测试性</strong>：一段代码能不能被有效地测试？接口设计得是否便于注入依赖和验证结果？SET 在设计阶段就介入，确保架构不是&quot;写出来容易，测试起来要命&quot;</li><li><strong>测试效率</strong>：测试能不能在合理时间内跑完？能不能并行？结果可不可靠？</li></ul><p>有一点值得特别注意：<strong>SET 的编码能力要求和 SWE 是同一标准。</strong> 在 Google，SET 的面试流程和 SWE 几乎一样——算法、数据结构、系统设计——区别只在于考察方向偏向测试场景。SET 写的代码（测试框架、工具、基础设施）和产品代码同等质量。</p><p>这意味着如果团队想招 SET，不是找一个手工测试人员培训写脚本就够了。SET 本质上是一个开发者，只是他的代码产出物是&quot;让测试变得更高效&quot;的工具，而不是产品功能。</p><h3 id="te-用户的代言人" tabindex="-1">TE：用户的代言人 <a class="header-anchor" href="#te-用户的代言人" aria-label="Permalink to &quot;TE：用户的代言人&quot;">​</a></h3><p>TE 是&quot;模拟真实用户&quot;的专家。他们的主要武器不是自动化脚本，而是<strong>探索式测试、场景思维、用户行为洞察</strong>。TE 关注的问题不是&quot;代码写对了吗&quot;，而是&quot;用户能用好吗&quot;：</p><ul><li>这个功能的操作流程符合用户直觉吗？</li><li>不同用户角色（新用户、VIP、管理员）的使用路径有什么差异？</li><li>在弱网、低端设备、非母语等真实场景下，体验怎么样？</li></ul><h3 id="三角色怎么协作" tabindex="-1">三角色怎么协作 <a class="header-anchor" href="#三角色怎么协作" aria-label="Permalink to &quot;三角色怎么协作&quot;">​</a></h3><p>一个典型的功能开发流程中，三个角色的配合是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET 在设计阶段介入 → 确保架构可测试</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>SWE 写功能代码 + 写单元测试 → 提交前测试认证通过</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>TE 在功能可运行时开始探索 → 从用户视角发现问题</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>三人一起在 Bug Council 上过发现的问题 → 共同决策优先级</span></span></code></pre></div><p>SET 和 TE 的比例不是 1:1——Google 的经验是 SET 数量通常多于 TE，因为自动化基础设施的投入产出比更高。但这个比例因项目而异。</p><h2 id="测试按规模分层-小、中、大" tabindex="-1">测试按规模分层：小、中、大 <a class="header-anchor" href="#测试按规模分层-小、中、大" aria-label="Permalink to &quot;测试按规模分层：小、中、大&quot;">​</a></h2><p>Google 不按传统的&quot;单元/集成/系统&quot;来分类测试，而是按<strong>规模和范围</strong>分三个等级。这种分类方式的核心是<strong>让测试的执行速度和隔离程度决定它的位置</strong>。</p><table tabindex="0"><thead><tr><th>测试等级</th><th>范围</th><th>特点</th><th>占比</th></tr></thead><tbody><tr><td><strong>小型测试</strong></td><td>单个函数或类，单进程单线程，无文件/网络 IO</td><td>毫秒级执行，完全隔离</td><td>~70%</td></tr><tr><td><strong>中型测试</strong></td><td>跨多个类或模块，可访问文件系统和数据库</td><td>秒级执行，单机多进程</td><td>~20%</td></tr><tr><td><strong>大型测试</strong></td><td>端到端全链路，可访问外部依赖</td><td>分钟级执行，分布式环境</td><td>~10%</td></tr></tbody></table><h3 id="为什么这样分" tabindex="-1">为什么这样分 <a class="header-anchor" href="#为什么这样分" aria-label="Permalink to &quot;为什么这样分&quot;">​</a></h3><p>传统的&quot;单元/集成/系统&quot;分类的问题在于——每个人对&quot;集成测试&quot;的定义不一样。一个测试到底该归为哪类，经常变成无聊的争论。</p><p>Google 的分类标准是<strong>客观可判定的</strong>：</p><ul><li>这个测试能不能在单进程中运行？能不能脱离网络？——如果能，就是小型</li><li>这个测试需要跨进程但还在一台机器上？——中型</li><li>需要分布式环境？——大型</li></ul><p>判断标准清楚了，自动化策略也清楚了：小型测试提交时跑、中型测试构建时跑、大型测试定时跑。</p><h3 id="金字塔比例的由来" tabindex="-1">金字塔比例的由来 <a class="header-anchor" href="#金字塔比例的由来" aria-label="Permalink to &quot;金字塔比例的由来&quot;">​</a></h3><p>70/20/10 不是拍脑袋定的。Google 的经验是：<strong>写一个小型测试的成本远低于中型，中型远低于大型。</strong> 不是&quot;大型测试不重要&quot;，而是&quot;同样的 bug，越早用越小的测试抓住成本越低&quot;。</p><p>如果你的测试分布反过来——10% 小型、70% 大型——那你的测试套件会越来越慢、越来越不稳定、越来越没人愿意跑。这就是 <a href="/testing/methodology/white-black-box.html">白盒与黑盒</a>讲的&quot;冰淇淋筒&quot;反模式。</p><h2 id="测试认证-代码提交前的质量门禁" tabindex="-1">测试认证：代码提交前的质量门禁 <a class="header-anchor" href="#测试认证-代码提交前的质量门禁" aria-label="Permalink to &quot;测试认证：代码提交前的质量门禁&quot;">​</a></h2><p>Google 有一套叫<strong>测试认证（Test Certification）</strong>的机制，本质上是一个自动化的质量门禁：<strong>代码在合入主干之前，必须通过一系列的自动化检查。</strong></p><p>测试认证通常包含：</p><ul><li>新增或修改的代码必须通过所有相关的小型测试</li><li>代码覆盖率不能低于预设门槛（通常是新增代码的覆盖率）</li><li>静态分析（lint、类型检查、安全扫描）零告警</li><li>如果改动涉及高风险模块，可能还需要中型测试和特定的性能测试通过</li></ul><blockquote><p>测试认证不是&quot;建议&quot;，是&quot;不通过就不能合并&quot;的硬约束。</p></blockquote><p>这套机制和持续交付的提交阶段（<a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>）是同一件事的不同叫法。它的核心价值是<strong>让质量检查自动化、前置化</strong>——而不是等到发布前才发现问题。</p><h3 id="可测试性设计-set-的核心价值" tabindex="-1">可测试性设计：SET 的核心价值 <a class="header-anchor" href="#可测试性设计-set-的核心价值" aria-label="Permalink to &quot;可测试性设计：SET 的核心价值&quot;">​</a></h3><p>测试认证能跑起来的背后，是 SET 在架构层面做的<strong>可测试性设计</strong>。如果一个系统没有设计为&quot;可测试的&quot;——依赖紧耦合、没法 Mock、数据流不透明——那么自动化测试要么没法写，要么写出来又慢又脆。</p><p>SET 在设计阶段会带着这些问题参与讨论：</p><ul><li>这个接口能不能被独立调用？还是必须经过前面三个步骤才能触发？</li><li>外部依赖能不能被替换为 Fake 或 Stub？</li><li>异步操作的结果能不能被观测到？</li><li>状态变更后能不能被验证？</li></ul><p>这些问题在架构阶段不被考虑，后面再多自动化也补不回来。</p><h2 id="工程生产力部门-测试组织如何设计" tabindex="-1">工程生产力部门：测试组织如何设计 <a class="header-anchor" href="#工程生产力部门-测试组织如何设计" aria-label="Permalink to &quot;工程生产力部门：测试组织如何设计&quot;">​</a></h2><p>Google 没有传统意义上的&quot;QA 部门&quot;。所有测试相关的角色统一归属到<strong>工程生产力部门（Engineering Productivity）</strong>。</p><h3 id="为什么这样设计" tabindex="-1">为什么这样设计 <a class="header-anchor" href="#为什么这样设计" aria-label="Permalink to &quot;为什么这样设计&quot;">​</a></h3><p>传统 QA 部门的困境：测试人员分散到各个产品团队后，容易被业务压得喘不过气——每天忙着手工回归、赶发布，没时间做工具建设和技能提升。但如果把测试人员集中到一个独立部门，又容易脱离业务——做的工具没人用、定的流程没人跟。</p><p>Google 的解法是：<strong>测试人员归工程生产力部门管，但同时嵌入到产品团队中工作。</strong> 他们的绩效考核不由产品经理决定，而是由工程生产力部门的经理负责。这样既保证了与业务团队的紧密协作，又让测试人员有条件专注于测试工程能力的建设。</p><h3 id="这个设计的三个价值" tabindex="-1">这个设计的三个价值 <a class="header-anchor" href="#这个设计的三个价值" aria-label="Permalink to &quot;这个设计的三个价值&quot;">​</a></h3><ol><li><strong>测试人员有职业发展路径</strong>：不只是&quot;测得好的 QA 被提拔为 QA Lead&quot;，而是可以沿着 SET（工具和基础设施）或 TE（用户研究和质量策略）两个方向深入发展</li><li><strong>测试基础设施被持续投入</strong>：因为有人专门负责，不是&quot;项目不忙的时候顺便搞一下&quot;</li><li><strong>测试方法论可以在全公司共享</strong>：一个团队发现的好做法，通过工程生产力部门可以推广到所有团队</li></ol><h3 id="对小团队的启示" tabindex="-1">对小团队的启示 <a class="header-anchor" href="#对小团队的启示" aria-label="Permalink to &quot;对小团队的启示&quot;">​</a></h3><p>你的团队可能没有 Google 的规模，不需要一个工程生产力部门。但这个设计背后的原则是通用的：</p><ul><li>测试人员不应该被当成&quot;开发后面的那个角色&quot;——他们需要有独立的技术成长空间</li><li>测试基础设施需要有人持续投入——不要让&quot;写自动化&quot;永远是最后一个优先级</li><li>测试方法论需要有人推动——不是靠&quot;规定&quot;，而是靠一个人一个人地影响</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>SWE（写代码+测试）、SET（建工具+关注可测试性，编码能力与SWE同等标准）、TE（探索+用户体验）三角色协作，质量从代码阶段内建</li><li>测试按规模分小/中/大三层——不按&quot;单元/集成/系统&quot;分，按客观的规模和隔离程度分，比例 70/20/10</li><li>测试认证是提交前的自动化质量门禁——不通过不能合入，让质量检查前置</li><li>可测试性设计是 SET 的核心价值——在架构阶段就确保代码能被高效测试，比事后补自动化重要得多</li><li>工程生产力部门的设计原则是通用的：测试人员需要独立的技术成长空间，测试基础设施需要有人持续投入</li></ol>`,54)])])}const q=o(n,[["render",r]]);export{g as __pageData,q as default};
